const dbRecord = $('Loop: oferta por oferta').item.json;
const dbId     = String(dbRecord.id     || '');
const dbUrl    = String(dbRecord.url    || '');
const dbPortal = String(dbRecord.portal || '');

const httpOut = $input.item.json;
const html    = typeof httpOut === 'string' ? httpOut
  : (httpOut.data || httpOut.body || httpOut.html || '');
const htmlStr = String(html);

console.log('[enrich-color] id=' + dbId + ' portal=' + dbPortal + ' html_len=' + htmlStr.length);

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}

// Filtra valores que NO son colores: versiones, acabados, combustibles, etc.
function isPlausibleColor(s) {
  if (!s) return false;
  const v = String(s).trim();
  if (v.length < 2 || v.length > 35) return false;
  if (/^\d+$/.test(v)) return false; // solo números
  if (/^#[0-9a-fA-F]{3,8}$/.test(v)) return false; // hex CSS
  if (/^rgba?\s*\(/.test(v)) return false; // rgb/rgba CSS
  const lc = v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const notColors = [
    'serie','series','basic','style','premium','edition','limited','executive',
    'elegance','sport','advance','active','comfort','luxury','select','dynamic',
    'business','design','motion','trend','urban','plus','pro','line','tech',
    'hybrid','electrico','diesel','gasolina','auto','manual','life','play',
    'move','cool','live','go','feel','energy','evolution','innovation','vision',
    'cross','allure','intens','attraction','ambition','gt','r-line','s-line',
    'titanium','ghia','ambiente','confort','reference','expression','initiale'
  ];
  if (notColors.some(function(w) {
    return lc === w || lc === w + 's' || lc.startsWith(w + ' ') || lc.endsWith(' ' + w);
  })) return false;
  return true;
}

if (!dbId || htmlStr.length < 500) {
  // HTML vacío o petición fallida — marcar enrich_tried_at para no reintentar hoy
  await new Promise(r => setTimeout(r, 300));
  const sql = 'UPDATE moveadvisor_market_offers SET enrich_tried_at = NOW(), updated_at = NOW() WHERE id = ' + esc(dbId);
  return [{ json: { id: dbId, colorFound: false, updateSql: dbId ? sql : null } }];
}

let colorVal = '';
let buildId  = '';

// ── ESTRATEGIA 1: JSON-LD (application/ld+json) ───────────────────────────
try {
  const blocks = [...htmlStr.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1].trim());
  console.log('[enrich-color] JSON-LD blocks=' + blocks.length);
  for (const b of blocks) {
    try {
      const j = JSON.parse(b);
      const arr = Array.isArray(j) ? j : (j['@graph'] || [j]);
      for (const o of arr) {
        if (!o) continue;
        const t = o['@type'] || '';
        const isVehicle = t === 'Car' || t === 'Product' || t === 'Vehicle'
          || t === 'Automobile' || t === 'MotorizedVehicle';
        if (!isVehicle) continue;
        const car = (o.offers && o.offers.itemOffered) || o;
        // Campo directo
        const c = car.color || o.color || car.colour || o.colour
          || car.colorName || o.colorName || car.exteriorColor || o.exteriorColor || '';
        if (c && isPlausibleColor(c)) { colorVal = c; break; }
        // additionalProperty [{name:'Color', value:'Rojo'}, ...] — patrón schema.org muy usado
        const props = [].concat(car.additionalProperty || o.additionalProperty || []);
        for (const p of props) {
          const pn = String(p.name || p.propertyID || '').toLowerCase();
          if (pn === 'color' || pn === 'colour' || pn === 'color exterior' || pn === 'color exterior') {
            const pv = String(p.value || '');
            if (isPlausibleColor(pv)) { colorVal = pv; break; }
          }
        }
        if (colorVal) break;
      }
      if (colorVal) break;
    } catch(e) { console.log('[enrich-color] JSON-LD block parse err: ' + e.message.slice(0,60)); }
  }
  if (colorVal) console.log('[enrich-color] JSON-LD color=' + colorVal);
  else if (blocks.length > 0) console.log('[enrich-color] JSON-LD no color. First block snippet: ' + blocks[0].slice(0, 200));
} catch(e) {
  console.log('[enrich-color] JSON-LD error: ' + e.message);
}

// ── ESTRATEGIA 2: __NEXT_DATA__ (Next.js SSR) ─────────────────────────────
// Funciona en: Flexicar, Autohero, y otros portales Next.js
if (!colorVal) {
  try {
    const ndMatch = htmlStr.match(/<script id="__NEXT_DATA__" type="application\/json">([\s\S]*?)<\/script>/);
    if (ndMatch) {
      const nd  = JSON.parse(ndMatch[1]);
      buildId   = nd.buildId || '';
      const pp  = (nd.props || {}).pageProps || {};

      // AutoScout24: bodyColor está en listingDetails.vehicle, no en pageProps directamente
      const as24v = ((pp.listingDetails || {}).vehicle || {});
      const as24c = as24v.bodyColor || as24v.bodyColorOriginal || '';
      if (as24c && isPlausibleColor(as24c)) {
        colorVal = as24c;
        console.log('[enrich-color] __NEXT_DATA__ as24 bodyColor=' + colorVal);
      }

      let v = pp.vehicle || pp.car || pp.data || pp.offer || pp.vehicleData || pp.detail || null;
      if (!v) {
        const is = (nd.props || {}).initialState || {};
        v = is.vehicle || is.car || null;
      }
      // TanStack / React Query dehydratedState
      if (!v && pp.dehydratedState) {
        const queries = (pp.dehydratedState.queries || []);
        for (const q of queries) {
          const d = (q.state || {}).data;
          if (!d) continue;
          if (d.color !== undefined || d.brand !== undefined) { v = d; break; }
          const nested = d.vehicle || d.car || d.data || null;
          if (nested && (nested.color !== undefined || nested.brand !== undefined)) { v = nested; break; }
          if (Array.isArray(d) && d.length > 0 && d[0].brand !== undefined) { v = d[0]; break; }
        }
      }
      if (v) {
        const cnd = v.color || v.colorName || v.colour || v.colorExterior
          || v.colorValue || v.exteriorColor || v.paintColor || '';
        colorVal = isPlausibleColor(cnd) ? cnd : '';
        if (colorVal) console.log('[enrich-color] __NEXT_DATA__ color=' + colorVal);
      }
    }
  } catch(e) {
    console.log('[enrich-color] __NEXT_DATA__ error: ' + e.message);
  }
}

// ── ESTRATEGIA 3: _next/data JSON (solo Flexicar, si buildId disponible) ──
if (!colorVal && dbPortal === 'flexicar' && buildId && dbUrl) {
  try {
    const slug    = dbUrl.split('/').filter(Boolean).pop() || '';
    const jsonUrl = 'https://www.flexicar.es/_next/data/' + buildId + '/coches-ocasion/' + slug + '.json';
    console.log('[enrich-color] flexicar _next/data: ' + jsonUrl);
    const jr   = await $helpers.httpRequest({
      method: 'GET',
      url: jsonUrl,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
        'Accept': 'application/json'
      }
    });
    const jRaw = typeof jr === 'string' ? JSON.parse(jr) : jr;
    const jpp  = (jRaw && jRaw.pageProps) ? jRaw.pageProps : {};
    const jv   = jpp.vehicle || jpp.car || jpp.data || jpp.offer || jpp.vehicleData || null;
    if (jv) {
      const cfx = jv.color || jv.colorName || jv.colour || jv.colorExterior
        || jv.colorValue || jv.exteriorColor || '';
      colorVal = isPlausibleColor(cfx) ? cfx : '';
      console.log('[enrich-color] flexicar _next/data color=' + colorVal);
    } else {
      console.log('[enrich-color] flexicar _next/data pp keys=' + Object.keys(jpp).join(','));
    }
  } catch(e) {
    console.log('[enrich-color] flexicar _next/data error: ' + e.message);
  }
}

// ── ESTRATEGIA 4: Regex genérico ──────────────────────────────────────────
if (!colorVal) {
  // 4a: todos los campos JSON "color":"..." — buscar el primero plausible
  const all1 = [...htmlStr.matchAll(/"color"\s*:\s*"([^"]{2,40})"/gi)];
  for (const m of all1) {
    const v = m[1].trim();
    if (!v.startsWith('#') && !/^rgb/i.test(v) && isPlausibleColor(v)) { colorVal = v; break; }
  }
}
if (!colorVal) {
  // 4b: microdata itemprop="color" — <span itemprop="color">Azul</span> o content="..."
  const m2a = htmlStr.match(/itemprop\s*=\s*["']color["'][^>]*content\s*=\s*["']([^"']{2,40})["']/i);
  const m2b = htmlStr.match(/itemprop\s*=\s*["']color["'][^>]*>([^<]{2,40})<\//i);
  const mVal = (m2a && m2a[1]) || (m2b && m2b[1]) || '';
  if (mVal && isPlausibleColor(mVal.trim())) colorVal = mVal.trim();
}
if (!colorVal) {
  // 4c: data-label / aria-label="Color" seguido de valor
  const m3 = htmlStr.match(/(?:data-label|aria-label)\s*=\s*["']Color["'][^>]*>([^<]{2,35})<\//i);
  if (m3 && isPlausibleColor(m3[1].trim())) colorVal = m3[1].trim();
}
if (!colorVal) {
  // 4d: patrón HTML etiqueta «Color» → siguiente elemento → valor
  // Maneja: <td>Color</td><td>Azul</td>  y  <span>Color</span><span class=...>Azul</span>
  const m4 = htmlStr.match(/[Cc]olor\s*<\/[a-z]+>\s*<[^>]{0,100}>\s*([A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ\s\-]{1,30})\s*<\//);
  if (m4 && isPlausibleColor(m4[1].trim())) colorVal = m4[1].trim();
}
if (!colorVal) {
  // 4e: JSON escapado en HTML — portales que embeben JSON con \"color\":\"Blanco\"
  // (OcasionPlus, y otros que JSON.stringify dentro de un atributo HTML)
  const unesc4e = htmlStr.replace(/\\"/g, '"');
  const all4e = [...unesc4e.matchAll(/"color"\s*:\s*"([^"]{2,40})"/gi)];
  for (const m of all4e) {
    const v = m[1].trim();
    if (!v.startsWith('#') && !/^rgb/i.test(v) && isPlausibleColor(v)) { colorVal = v; break; }
  }
}
if (colorVal) console.log('[enrich-color] regex fallback color=' + colorVal);
else console.log('[enrich-color] no color encontrado con ninguna estrategia');

console.log('[enrich-color] FINAL portal=' + dbPortal + ' color=' + colorVal);

// ── SQL ────────────────────────────────────────────────────────────────────
const sets = ['enrich_tried_at = NOW()'];
if (colorVal) sets.push('color = COALESCE(NULLIF(color,\'\'), ' + esc(colorVal) + ')');

const updateSql = 'UPDATE moveadvisor_market_offers SET '
  + sets.join(', ') + ', updated_at = NOW() WHERE id = ' + esc(dbId);

await new Promise(r => setTimeout(r, 600));
return [{ json: { id: dbId, colorFound: !!colorVal, updateSql: updateSql } }];
